function extremesGcd(nums: number[]): number {
  let lo = nums[0], hi = nums[0];
  for (const x of nums) { if (x < lo) lo = x; if (x > hi) hi = x; }
  for (let d = lo; d > 1; d--) if (lo % d === 0 && hi % d === 0) return d;
  return 1;
}

